select s.id,s.user_id,s.name,s.status,s.recurrence_type,s.branch_id,s.fulfillment_type,s.next_run_at,b.is_active as branch_active,jsonb_agg(jsonb_build_object('product_id',i.product_id,'name_ar',p.name_ar,'is_active',p.is_active,'quantity',i.quantity,'selected_options',i.selected_options)) as items from subscriptions.customer_product_subscriptions s join core.branches b on b.id=s.branch_id join subscriptions.customer_product_subscription_items i on i.subscription_id=s.id join catalog.products p on p.id=i.product_id where s.user_id='534c5b4d-cd2a-4234-b0a0-404000bf0ff4' group by s.id,b.is_active order by s.created_at desc;
